export type WidgetInfo = { kind: WidgetKind, name: string, category: string, about: string, allowed: boolean, suggested: boolean, };
export type StudioState = "missing" | "protected" | "ready";
export type StudioPlan = "unverified" | "free" | "launch" | "pro" | "founders";
export type OffTrack = "inherit" | "alwaysVisible" | "hide";
export type ShowIn = { practice: boolean, qualifying: boolean, race: boolean, };
export type Coordinate = number;
export type Point = { x: Coordinate, y: Coordinate, };
