export type FrequencyView = { overrideHz: number | null, appliedHz: number, source: FrequencySource, level: import('./settings').PerformanceLevel, };
export type FrequencyChange = number | null;
export type FrequencySource = "level" | "override" | "snapshot";
export type OverlayInstance = { id: string, kind: WidgetKind, settings: WidgetSettings | null, frequency: FrequencyView, visible: boolean, locked: boolean, opacity: number, showIn: ShowIn, offTrack: OffTrack, size: OverlaySize, x: Coordinate, y: Coordinate, sizeMode: SizeMode, aspectLocked: boolean, canvasPlacement: CanvasPlacement, };
export type StudioView = { state: StudioState, revision: string, instances: Array<OverlayInstance>, catalog: Array<WidgetInfo>, showing: boolean, plan: StudioPlan, canUndo: boolean, canRedo: boolean, canvas: CanvasView | null, monitor: OverlaySize | null, };
